{
  "name": "feth-korteji-live-studio",
  "version": "2.2.0",
  "description": "3D Osmanlı/Selçuklu TikTok Live kortej oyun sistemi",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "test": "node test/server.test.js",
    "generate-models": "for f in blender/*.py; do blender -b --python \"$f\"; done"
  },
  "dependencies": {
    "express": "^5.1.0",
    "socket.io": "^4.8.1",
    "tiktok-live-connector": "latest"
  }
}

const express = require('express');
const http = require('http');
const { Server } = require('socket.io');
const fs = require('fs');
const path = require('path');

let TikTokLive;
try { ({ WebcastPushConnection: TikTokLive } = require('tiktok-live-connector')); }
catch (e) { console.warn('TikTok connector yüklenemedi:', e.message); }

const app = express();
const server = http.createServer(app);
const io = new Server(server, { cors: { origin: '*' } });
const ROOT = __dirname;
const PORT = process.env.PORT || 3002;

app.use(express.json({ limit: '1mb' }));
app.use(express.static(path.join(ROOT, 'public')));

const readJson = (file, fallback) => {
  try { return JSON.parse(fs.readFileSync(file, 'utf8')); } catch { return fallback; }
};
const writeJson = (file, value) => fs.writeFileSync(file, JSON.stringify(value, null, 2));

const giftsFile = path.join(ROOT, 'data/tiktok_gifts_cache.json');
const mappingFile = path.join(ROOT, 'config/gifts_mapping.json');
const leaderboardFile = path.join(ROOT, 'data/leaderboard.json');
for (const [file, value] of [[mappingFile, {}], [leaderboardFile, { players: [], stats: {} }]]) {
  if (!fs.existsSync(file)) writeJson(file, value);
}

let liveConnection = null;
let liveState = { status: 'Beklemede', username: null, viewerCount: 0, likes: 0, coins: 0 };

const avatarCache = new Map();
app.get('/api/avatar', async (req, res) => {
  const url = req.query.url;
  if (!url || !/^https:\/\/(?:[^\s/]+\.)?(?:tiktokcdn\.com|tiktokcdn-us\.com)/i.test(url)) return res.status(400).end();
  if (avatarCache.has(url)) return res.type('png').send(avatarCache.get(url));
  try {
    const response = await fetch(url);
    if (!response.ok) throw new Error(`Avatar HTTP ${response.status}`);
    const buffer = Buffer.from(await response.arrayBuffer());
    avatarCache.set(url, buffer);
    res.set('Cache-Control', 'public, max-age=86400').type(response.headers.get('content-type') || 'image/jpeg').send(buffer);
  } catch (error) { res.status(502).json({ error: 'Avatar indirilemedi' }); }
});

app.get('/api/status', (_, res) => res.json(liveState));
app.get('/api/gifts', (_, res) => res.json(readJson(giftsFile, [])));
app.get('/api/mappings', (_, res) => res.json(readJson(mappingFile, {})));
app.post('/api/mappings', (req, res) => {
  writeJson(mappingFile, req.body || {});
  io.emit('config:update', req.body);
  res.json({ ok: true });
});
app.get('/api/leaderboard', (_, res) => res.json(readJson(leaderboardFile, { players: [], stats: {} })));
app.post('/api/leaderboard', (req, res) => {
  writeJson(leaderboardFile, req.body);
  io.emit('leaderboard:update', req.body);
  res.json({ ok: true });
});

function setStatus(status, extra = {}) {
  liveState = { ...liveState, status, ...extra };
  io.emit('live:status', liveState);
  console.log('[TikTok Live]', liveState.status, liveState.username || '');
}

async function connectTikTok(username) {
  if (!TikTokLive) return setStatus('Hata', { error: 'tiktok-live-connector kurulu değil' });
  await disconnectTikTok(false);
  const clean = username.replace(/^@/, '').trim();
  if (!clean) return setStatus('Hata', { error: 'Kullanıcı adı gerekli' });
  liveState = { status: 'Bağlanıyor', username: clean, viewerCount: 0, likes: 0, coins: 0 };
  io.emit('live:status', liveState);

  liveConnection = new TikTokLive(clean, { processInitialData: false, enableExtendedGiftInfo: true, reconnectOnError: true, reconnectIntervalMs: 3000 });
  liveConnection.connect().then(async state => {
    setStatus('Bağlandı', { viewerCount: state?.roomInfo?.userCount || liveState.viewerCount });
    try {
      const gifts = await liveConnection.getAvailableGifts();
      const normalized = (gifts || []).map(g => ({ id: g.gift_id ?? g.id, name: g.name, diamond: g.diamond_count ?? g.diamondCost ?? g.diamond_count ?? 0, image: g.image?.url_list?.[0] || g.icon?.url_list?.[0] || g.image_url || g.icon_url || '' }));
      writeJson(giftsFile, normalized);
      io.emit('gifts:update', normalized);
      console.log(`[Hediye Kataloğu] ${normalized.length} hediye cache'lendi`);
    } catch (e) { console.warn('[Hediye Kataloğu]', e.message); }
  }).catch(error => setStatus('Hata/Yeniden Bağlanıyor', { error: error.message }));

  liveConnection.on('chat', data => io.emit('live:event', normalizeEvent('chat', data, data.comment)));
  liveConnection.on('like', data => {
    const count = data.likeCount || 1;
    liveState.likes += count;
    io.emit('live:stats', liveState);
    io.emit('live:event', normalizeEvent('like', data, `+${count} beğeni`));
  });
  liveConnection.on('member', data => io.emit('live:event', normalizeEvent('member', data, 'odaya katıldı')));
  liveConnection.on('gift', data => {
    if (data.giftType === 1 && data.repeatEnd === false) return;
    const coins = (data.repeatCount || 1) * (data.giftDiamondCount || data.diamondCount || data.gift?.diamond_count || 0);
    liveState.coins += coins;
    io.emit('live:stats', liveState);
    io.emit('live:event', normalizeEvent('gift', data, data.giftName || data.gift?.name || 'Hediye', coins));
  });
  liveConnection.on('roomUser', data => { liveState.viewerCount = data.viewerCount || data.userCount || liveState.viewerCount; io.emit('live:stats', liveState); });
  liveConnection.on('disconnected', () => setStatus('Bağlantı Kesildi'));
  liveConnection.on('error', error => setStatus('Hata/Yeniden Bağlanıyor', { error: error.message }));
}

function normalizeEvent(type, data, label, coins = 0) {
  const user = data.user || data.uniqueId || data.nickname || {};
  return {
    type, label, coins,
    uniqueId: data.uniqueId || user.uniqueId || user.unique_id || 'misafir',
    nickname: data.nickname || user.nickname || user.uniqueId || 'Misafir',
    profilePictureUrl: data.profilePictureUrl || user.profilePictureUrl || user.profile_picture?.url_list?.[0] || '',
    repeatCount: data.repeatCount || 1,
    timestamp: Date.now()
  };
}

async function disconnectTikTok(update = true) {
  if (liveConnection) { try { liveConnection.disconnect(); } catch {} liveConnection = null; }
  if (update) setStatus('Bağlantı Kesildi', { username: null });
}

io.on('connection', socket => {
  socket.emit('live:status', liveState);
  socket.emit('gifts:update', readJson(giftsFile, []));
  socket.emit('config:update', readJson(mappingFile, {}));
  socket.emit('leaderboard:update', readJson(leaderboardFile, { players: [], stats: {} }));
  socket.on('live:connect', ({ username }) => connectTikTok(username));
  socket.on('live:disconnect', () => disconnectTikTok());
  socket.on('live:test', event => io.emit('live:event', { ...event, type: event.type || 'gift', timestamp: Date.now(), profilePictureUrl: event.profilePictureUrl || '' }));
  socket.on('game:settings', settings => io.emit('game:settings', settings));
  socket.on('leaderboard:kick', ({ uniqueId }) => {
    const board = readJson(leaderboardFile, { players: [], stats: {} });
    board.players = (board.players || []).filter(p => p.uniqueId !== uniqueId);
    writeJson(leaderboardFile, board);
    io.emit('leaderboard:update', board);
  });
  socket.on('leaderboard:reset', () => {
    const board = { players: [], stats: { likes: 0, coins: 0 } };
    writeJson(leaderboardFile, board);
    io.emit('leaderboard:update', board);
  });
});

server.listen(PORT, '0.0.0.0', () => console.log(`Fetih Korteji çalışıyor: http://0.0.0.0:${PORT}`));

export class FetihSoundEngine {
  constructor(){this.ctx=null;this.master=null;this.ambience=null;this.volume=.7;this.muted=false}
  init(){if(this.ctx)return;this.ctx=new (window.AudioContext||window.webkitAudioContext)();this.master=this.ctx.createGain();this.master.gain.value=this.muted?0:this.volume;this.master.connect(this.ctx.destination);this.ctx.resume();this.startAmbience()}
  setVolume(v){this.volume=Math.max(0,Math.min(1,v));if(this.master&&!this.muted)this.master.gain.setTargetAtTime(this.volume,this.ctx.currentTime,.05)}
  setMuted(m){this.muted=m;if(this.master)this.master.gain.setTargetAtTime(m?0:this.volume,this.ctx.currentTime,.02)}
  noise(duration=1){const ctx=this.ctx,n=ctx.createBufferSource(),b=ctx.createBuffer(1,ctx.sampleRate*duration,ctx.sampleRate),d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=(Math.random()*2-1)*(1-i/d.length);n.buffer=b;return n}
  startAmbience(){this.init();clearInterval(this.ambience);let step=0;this.ambience=setInterval(()=>{if(!this.ctx||this.muted)return;const t=this.ctx.currentTime,osc=this.ctx.createOscillator(),gain=this.ctx.createGain();osc.type='sine';osc.frequency.setValueAtTime(68,t);osc.frequency.exponentialRampToValueAtTime(42,t+.12);gain.gain.setValueAtTime(.018,t);gain.gain.exponentialRampToValueAtTime(.001,t+.18);osc.connect(gain).connect(this.master);osc.start(t);osc.stop(t+.19);if(step++%4===0)this.metalJingle()},250)}
  metalJingle(){const n=this.noise(.025),f=this.ctx.createBiquadFilter(),g=this.ctx.createGain();f.type='highpass';f.frequency.value=5000;g.gain.value=.012;n.connect(f).connect(g).connect(this.master);n.start()}
  playMehterDrum(){this.init();const ctx=this.ctx,t=ctx.currentTime;for(let i=0;i<3;i++){const o=ctx.createOscillator(),g=ctx.createGain();o.type='triangle';o.frequency.setValueAtTime(110+i*4,t+i*.35);o.frequency.exponentialRampToValueAtTime(40,t+.18+i*.35);g.gain.setValueAtTime(.28,t+i*.35);g.gain.exponentialRampToValueAtTime(.001,t+.35+i*.35);o.connect(g).connect(this.master);o.start(t+i*.35);o.stop(t+.38+i*.35)}const n=this.noise(.16),f=ctx.createBiquadFilter(),g=ctx.createGain();f.type='highpass';f.frequency.value=3500;g.gain.value=.12;n.connect(f).connect(g).connect(this.master);n.start(t)}
  playCatapultFire(){this.init();const ctx=this.ctx,t=ctx.currentTime,n=this.noise(1.1),f=ctx.createBiquadFilter(),g=ctx.createGain();f.type='bandpass';f.frequency.setValueAtTime(180,t);f.frequency.exponentialRampToValueAtTime(2400,t+.7);g.gain.setValueAtTime(.08,t);g.gain.exponentialRampToValueAtTime(.001,t+1);n.connect(f).connect(g).connect(this.master);n.start(t);setTimeout(()=>this.explosion(),650)}
  explosion(){const ctx=this.ctx,t=ctx.currentTime,n=this.noise(.8),f=ctx.createBiquadFilter(),g=ctx.createGain(),o=ctx.createOscillator(),og=ctx.createGain();f.type='lowpass';f.frequency.value=600;g.gain.setValueAtTime(.55,t);g.gain.exponentialRampToValueAtTime(.001,t+.8);n.connect(f).connect(g).connect(this.master);n.start(t);o.frequency.setValueAtTime(75,t);o.frequency.exponentialRampToValueAtTime(25,t+.5);og.gain.setValueAtTime(.5,t);og.gain.exponentialRampToValueAtTime(.001,t+.6);o.connect(og).connect(this.master);o.start(t);o.stop(t+.65)}
  playHorseNeigh(){this.init();const ctx=this.ctx,t=ctx.currentTime;const o=ctx.createOscillator(),mod=ctx.createOscillator(),mg=ctx.createGain(),f=ctx.createBiquadFilter(),g=ctx.createGain();o.type='sawtooth';o.frequency.value=520;mod.frequency.value=13;mg.gain.value=180;mod.connect(mg).connect(o.frequency);f.type='bandpass';f.frequency.value=1200;g.gain.setValueAtTime(.12,t);g.gain.exponentialRampToValueAtTime(.001,t+.9);o.connect(f).connect(g).connect(this.master);o.start(t);mod.start(t);o.stop(t+.95);mod.stop(t+.95);for(let i=0;i<4;i++){const n=this.noise(.09),nf=ctx.createBiquadFilter(),ng=ctx.createGain();nf.type='lowpass';nf.frequency.value=220;ng.gain.setValueAtTime(.12,t+.9+i*.14);ng.gain.exponentialRampToValueAtTime(.001,t+1.02+i*.14);n.connect(nf).connect(ng).connect(this.master);n.start(t+.9+i*.14)}}
  playGrandSeal(){this.init();const ctx=this.ctx,t=ctx.currentTime;const o=ctx.createOscillator(),g=ctx.createGain();o.frequency.setValueAtTime(54,t);o.frequency.exponentialRampToValueAtTime(24,t+.8);g.gain.setValueAtTime(.65,t);g.gain.exponentialRampToValueAtTime(.001,t+1.2);o.connect(g).connect(this.master);o.start(t);o.stop(t+1.25);for(let i=0;i<5;i++){const ring=ctx.createOscillator(),rg=ctx.createGain();ring.type='sine';ring.frequency.value=[330,467,612,880,1200][i];rg.gain.setValueAtTime(.09,t+.15);rg.gain.exponentialRampToValueAtTime(.001,t+2.4);ring.connect(rg).connect(this.master);ring.start(t+.15);ring.stop(t+2.5)}}
  playVizierFanfare(){this.init();const ctx=this.ctx,t=ctx.currentTime;const notes=[196,247,294,196,370,440];notes.forEach((freq,i)=>{const o=ctx.createOscillator(),f=ctx.createBiquadFilter(),g=ctx.createGain();o.type='sawtooth';o.frequency.value=freq;f.type='lowpass';f.frequency.value=1600;g.gain.setValueAtTime(.08,t+i*.22);g.gain.exponentialRampToValueAtTime(.001,t+.34+i*.22);o.connect(f).connect(g).connect(this.master);o.start(t+i*.22);o.stop(t+.36+i*.22)})}
}
window.fetihSound=new FetihSoundEngine();window.addEventListener('pointerdown',()=>window.fetihSound.init(),{once:true});

import * as THREE from 'three';

const host=document.getElementById('game');
const renderer=new THREE.WebGLRenderer({antialler:true,antialias:true,powerPreference:'high-performance'});
renderer.setPixelRatio(Math.min(devicePixelRatio,2));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;host.appendChild(renderer.domElement);
const scene=new THREE.Scene();scene.background=new THREE.Color(0x100b08);scene.fog=new THREE.FogExp2(0x100b08,.018);
const camera=new THREE.PerspectiveCamera(38,innerWidth/innerHeight,.1,500);
const clock=new THREE.Clock();const players=new Map();const particles=[];

const gold=new THREE.MeshStandardMaterial({color:0xd6a84b,metalness:.75,roughness:.28});
const red=new THREE.MeshStandardMaterial({color:0x7d1d18,roughness:.7});
const steel=new THREE.MeshStandardMaterial({color:0x9ca0a0,metalness:.85,roughness:.22});
const stone=new THREE.MeshStandardMaterial({color:0x77705f,roughness:.9});

scene.add(new THREE.HemisphereLight(0xffddaa,0x24150e,2));const sun=new THREE.DirectionalLight(0xffcf83,3);sun.position.set(-20,35,20);sun.castShadow=true;scene.add(sun);

const road=new THREE.Group();for(let z=-90;z<90;z+=4){const slab=new THREE.Mesh(new THREE.BoxGeometry(12,.35,3.7),stone);slab.position.set(0,-.18,z);slab.receiveShadow=true;road.add(slab)}
for(const side of [-1,1]){for(let z=-84;z<85;z+=16){const c=new THREE.Mesh(new THREE.CylinderGeometry(.18,.22,4,8),new THREE.MeshStandardMaterial({color:0x3e2417,roughness:.8}));c.position.set(side*8,1.4,z);c.castShadow=true;road.add(c);const flame=new THREE.Mesh(new THREE.ConeGeometry(.35,.9,8),new THREE.MeshBasicMaterial({color:0xff7616}));flame.position.set(side*8,3.2,z);road.add(flame)}}
for(let i=-3;i<=3;i++){const gate=new THREE.Mesh(new THREE.TorusGeometry(3.4,.28,8,24,Math.PI),gold);gate.position.set(i*13,3,-38);gate.rotation.z=Math.PI;gate.castShadow=true;road.add(gate)}
for(let i=-2;i<=2;i++){const dome=new THREE.Mesh(new THREE.SphereGeometry(2,12,8,0,Math.PI*2,0,Math.PI/2),red);dome.scale.y=.65;dome.position.set(i*8,4,-92);road.add(dome)}scene.add(road);

const throne=new THREE.Group();for(const x of [-2.4,2.4]){const leg=new THREE.Mesh(new THREE.BoxGeometry(.35,3,.35),gold);leg.position.set(x,1.5,0);throne.add(leg)}const seat=new THREE.Mesh(new THREE.BoxGeometry(5.2,.7,3),red);seat.position.y=3.2;seat.castShadow=true;throne.add(seat);const back=new THREE.Mesh(new THREE.BoxGeometry(5.2,5,.45),gold);back.position.set(0,5.5,-1.2);throne.add(back);throne.position.set(0,0,-104);scene.add(throne);

function makeSoldier(index){const g=new THREE.Group();const body=new THREE.Mesh(new THREE.CapsuleGeometry(.38,1.15,4,8),red);body.position.y=1.2;body.castShadow=true;g.add(body);const helm=new THREE.Mesh(new THREE.SphereGeometry(.42,10,8),steel);helm.position.y=2.25;helm.castShadow=true;g.add(helm);const plume=new THREE.Mesh(new THREE.ConeGeometry(.12,.8,6),gold);plume.position.set(0,2.85,.12);plume.rotation.x=.15;g.add(plume);const armGeo=new THREE.CylinderGeometry(.1,.11,.95,6);for(const x of [-.48,.48]){const arm=new THREE.Mesh(armGeo,red);arm.position.set(x,1.35,0);arm.rotation.z=x>0?-1.05:1.05;g.add(arm)}const spear=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,3.1,5),gold);spear.position.set(.65,1.45,-.15);g.add(spear);const avatarFrame=new THREE.Mesh(new THREE.CircleGeometry(.46,16),new THREE.MeshStandardMaterial({color:0xf1db8a,emissive:0x241400,side:THREE.DoubleSide}));avatarFrame.position.set(0,2.45,.39);avatarFrame.name='AvatarFrame';g.add(avatarFrame);g.userData.phase=Math.random()*6;g.userData.walk=1.4+Math.random()*.25;return g}

const catapults=[];for(const side of [-1,1]){const c=new THREE.Group();const wood=new THREE.MeshStandardMaterial({color:0x5b3821,roughness:.75});const base=new THREE.Mesh(new THREE.BoxGeometry(2.4,.25,2),wood);base.position.y=.15;c.add(base);const arm=new THREE.Mesh(new THREE.BoxGeometry(.18,.18,3),wood);arm.position.set(0,1.1,.3);arm.rotation.x=-.35;c.add(arm);c.position.set(side*9,0,-15);c.userData.side=side;scene.add(c);catapults.push(c)}

function rankColor(rank){return rank==='Vezir'?0xffd47a:rank==='Sancaktar'?0xc9c7c2:rank==='Sipahi'?0x4aa0a2:0x7d1d18}

function createPlayer(ev,index){const id=ev.uniqueId||`misafir-${index}`;if(players.has(id))return players.get(id);const g=makeSoldier(index);g.userData={id,nickname:ev.nickname||id,rank:'Nefer',score:0,avatar:'',target:new THREE.Vector3(),phase:g.userData.phase};scene.add(g);players.set(id,g);if(players.size>150){const oldest=players.keys().next().value;const old=players.get(oldest);scene.remove(old);players.delete(oldest)}applyAvatar(g,ev.profilePictureUrl);reorder();return g}

async function applyAvatar(g,url){if(!url)return;try{const tx=new THREE.TextureLoader().load(`/api/avatar?url=${encodeURIComponent(url)}`,t=>{t.colorSpace=THREE.SRGBColorSpace;const frame=g.getObjectByName('AvatarFrame');if(frame)frame.material=new THREE.MeshBasicMaterial({map:t,side:THREE.DoubleSide})})}catch(e){}}

function reorder(){const arr=[...players.values()].sort((a,b)=>(b.userData.score||0)-(a.userData.score||0));arr.forEach((g,i)=>{const rankIndex=g.userData.rank==='Vezir'?0:g.userData.rank==='Sancaktar'?1:g.userData.rank==='Sipahi'?2:3;const lane=(i%7)-3;const row=Math.floor(i/7);g.userData.target.set(lane*1.45,0,rankIndex*-6-row*.9+22)});}

for(let i=0;i<24;i++){const g=makeSoldier(i);g.userData={id:'demo-'+i,nickname:'Nefer '+i,rank:i<3?'Sancaktar':i<8?'Sipahi':'Nefer',score:150-i*4,target:new THREE.Vector3()};scene.add(g);players.set(g.userData.id,g)}reorder();

function setBanner(text){const b=document.getElementById('banner');b.textContent=text;b.classList.add('show');clearTimeout(setBanner.t);setBanner.t=setTimeout(()=>b.classList.remove('show'),4200)}

let cameraMode='court';let cameraUntil=0;let shake=0;const defaultPos=()=>new THREE.Vector3(21,19,42);
function action(ev){if(ev.type==='like'||ev.type==='chat'&&ev.label?.toLowerCase().includes('katil'))return joinMarch(ev);if(ev.type==='member')return joinMarch(ev);if(!ev.action&&!ev.giftName)return;return processAction(ev.action||resolveGift(ev),ev)}
function resolveGift(ev){const diamond=ev.coins||ev.diamond||0;if(diamond>=500)return'RANK_VIZIER';if(diamond>=300)return'EVENT_SEAL';if(diamond>=100)return'RANK_CAVALRY';if(diamond>=50)return'EVENT_CATAPULT';if(diamond>=30)return'EVENT_MEHTER';if(diamond>=10)return'RANK_SANCAKTAR';if(diamond>0)return'RANK_SIPAHI';return'JOIN_MARCH'}
function joinMarch(ev){const g=createPlayer(ev,players.size);g.userData.score=(g.userData.score||0)+1;g.userData.rank='Nefer';reorder();setBanner(`${g.userData.nickname} safa katıldı!`)}
function processAction(actionId,ev){const g=createPlayer(ev,players.size);if(actionId==='RANK_SIPAHI'){g.userData.rank='Sipahi';g.userData.score+=10}if(actionId==='RANK_SANCAKTAR'){g.userData.rank='Sancaktar';g.userData.score+=25;cinematic(g,3000)}if(actionId==='RANK_CAVALRY'){g.userData.rank='Atlı';g.userData.score+=100;window.fetihSound.playHorseNeigh();cinematic(g,3000)}if(actionId==='EVENT_MEHTER'){window.fetihSound.playMehterDrum();cameraMode='mehter';cameraUntil=clock.elapsedTime+8;setBanner('MEHTER TAKIMI COŞKUSU');}if(actionId==='EVENT_CATAPULT'){window.fetihSound.playCatapultFire();shake=.8;cameraMode='catapult';cameraUntil=clock.elapsedTime+4;setBanner('MANÇINIK SALDIRISI · +100 PUAN');g.userData.score+=100}if(actionId==='EVENT_SEAL'){window.fetihSound.playGrandSeal();shake=.9;cinematic(g,4000);setBanner(`${g.userData.nickname} · 60 SANİYE DOKUNULMAZLIK`)}if(actionId==='RANK_VIZIER'){g.userData.rank='Vezir';g.userData.score+=500;window.fetihSound.playVizierFanfare();cinematic(g,5000);setBanner(`FERMAN: ${g.userData.nickname.toUpperCase()} BAŞKOMUTAN OLDU`)}reorder()}
function cinematic(g,duration){cameraMode='subject';g.userData.cameraUntil=clock.elapsedTime+duration/1000}

